  saveState(appState);
  showToast(`Created goal: ${name}`, 'success');
  closeModal('create-goal-modal');
  renderGoals(currentGoalFilter);
  renderDashboard();

  const form = document.getElementById('create-goal-form');
  if (form) form.reset();
